        let mask = parse_mask("?l?d", &NO_CUSTOM).unwrap();
        assert_eq!(mask.positions.len(), 2);
        assert_eq!(mask.positions[0].len(), 26); // lowercase
        assert_eq!(mask.positions[1].len(), 10); // digits
    }

