pub fn filter_for_worker_index(
    passwords: impl Iterator<Item = Vec<u8>>,
    worker_count: usize,
    index: usize,
) -> impl Iterator<Item = Vec<u8>> {
    if worker_count > 1 {
        Either::Left(passwords.enumerate().filter_map(move |(i, line)| {
            if i % worker_count == index - 1 {
                Some(line)
            } else {
                None
            }
        }))
    } else {
        Either::Right(passwords)
    }
}

